import json
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

def fetch(url):
    try:
        with urlopen(url, timeout=10) as response:
            return json.load(response)
    except HTTPError as error:
        print("HTTP error:", error.code, error.reason)
    except URLError:
        print("Network error: could not reach the server")
    except json.JSONDecodeError as error:
        print("Not JSON:", error.msg)
    return None

print(fetch("https://jsonplaceholder.typicode.com/todos/1"))
print(fetch("https://jsonplaceholder.typicode.com/todos/99999"))
print(fetch("https://nonexistent.invalid/api"))
